def fetch_geofabrik(self, **kwargs):
    """
    Fetch collection-level metadata from Geofabrik OpenStreetMap Data Extracts.

    Geofabrik provides a GeoJSON index of all available regional extracts
    at https://download.geofabrik.de/index-v1.json. This is the sole official
    machine-readable catalog API for the Geofabrik download server, listing
    all available OSM regional extracts as a GeoJSON FeatureCollection.
    """
    import json

    dataset_url = kwargs.get('dataset_url', '')
    dataset_name = kwargs.get('dataset_name', '')
    doi = kwargs.get('doi', '')
    doi_landing_page = kwargs.get('doi_landing_page', '')

    # At least one identifier is required to confirm the caller intends Geofabrik
    if not dataset_url and not dataset_name and not doi and not doi_landing_page:
        return {"error": "缺少关键参数：需要 dataset_url、dataset_name、doi 或 doi_landing_page 中的至少一个"}

    url = "https://download.geofabrik.de/index-v1.json"

    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; MetadataCollector/1.0)"
    }

    response = self._get_with_retry(url, headers=headers)

    if response is None:
        return {"error": "No response from Geofabrik API"}

    if not hasattr(response, 'text') or not response.text:
        return {"error": "Empty response body from Geofabrik API"}

    try:
        data = response.json()
    except (json.JSONDecodeError, ValueError) as e:
        return {"error": f"Failed to parse JSON response: {e}", "raw_preview": response.text[:500]}

    if data is None:
        return {"error": "Response parsed as null/None from Geofabrik API"}

    if isinstance(data, dict) and not data:
        return {"error": "Empty JSON object from Geofabrik API"}

    return {
        "source": "Geofabrik OpenStreetMap Data Extracts",
        "format": "json",
        "data": data
    }

