def fetch_tpdc(self, **kwargs):
    import re
    import json

    doi = kwargs.get('doi')
    dataset_url = kwargs.get('dataset_url')
    doi_landing_page = kwargs.get('doi_landing_page')
    dataset_name = kwargs.get('dataset_name')

    # Step 1: Extract UUID from available sources (waterfall)
    uuid_val = None
    uuid_pattern = r'/data/([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})'

    # Path 1: Extract from dataset_url
    if dataset_url:
        m = re.search(uuid_pattern, dataset_url)
        if m:
            uuid_val = m.group(1)

    # Path 2: Extract from doi_landing_page
    if not uuid_val and doi_landing_page:
        m = re.search(uuid_pattern, doi_landing_page)
        if m:
            uuid_val = m.group(1)

    # Path 3: If we have a DOI but no UUID, resolve via doi.org redirect
    if not uuid_val and doi:
        try:
            doi_resolve_url = f"https://doi.org/{doi}"
            resp = self._get_with_retry(doi_resolve_url, timeout=10)
            if hasattr(resp, 'url') and resp.url:
                final_url = resp.url
                m = re.search(uuid_pattern, final_url)
                if m:
                    uuid_val = m.group(1)
        except Exception:
            pass

    # Defensive: if still no UUID, return error
    if not uuid_val:
        return {
            "error": "无法从提供的参数中解析出 TPDC 内部 UUID。请提供 dataset_url 或 doi_landing_page（格式：.../data/{UUID}）"
        }

    # Step 2: Call the TPDC exportJsonMetadata API
    api_url = f"https://data.tpdc.ac.cn/view/export/exportJsonMetadata?metadataId={uuid_val}"

    try:
        response = self._get_with_retry(api_url)
        response.raise_for_status()
    except Exception as e:
        return {"error": f"TPDC API 请求失败: {str(e)}"}

    # Step 3: Parse JSON response
    try:
        data = response.json()
    except json.JSONDecodeError as e:
        return {"error": f"TPDC API 返回非 JSON 数据: {str(e)}", "raw": response.text[:500]}

    # Validate: API returns null for invalid UUIDs
    if data is None:
        return {"error": f"TPDC API 返回 null，UUID '{uuid_val}' 可能无效"}

    return {
        "source": "National Tibetan Plateau Data Center (TPDC)",
        "format": "json",
        "data": data
    }

