    """
    Fetch NHDPlus HR collection-level metadata from USGS ScienceBase Catalog REST API
    by resolving the dataset DOI through the Handle system.

    API Chain:
      1. Handle API: https://doi.org/api/handles/{doi}  (DOI -> ScienceBase URL)
      2. ScienceBase Catalog REST API: https://www.sciencebase.gov/catalog/item/{item_id}?format=json

    The ScienceBase Catalog is the authoritative, native metadata registry for all 
    USGS data releases including The National Map staged products.
    """
    import re
    import json

    doi = kwargs.get('doi')

    if not doi:
        return {"error": "DOI parameter is required"}

    # --- Resolve DOI to ScienceBase URL via Handle API ---
    try:
        h = self._get_with_retry(f"https://doi.org/api/handles/{doi}")
        hd = h.json()
    except json.JSONDecodeError:
        return {"error": "Handle API returned non-JSON"}
    except Exception as e:
        return {"error": f"Handle API failed: {e}"}

    values = hd.get('values')
    if not values:
        return {"error": "Handle response missing values array"}

    sb_url = None
    for v in values:
        if v.get('type') == 'URL':
            sb_url = v.get('data', {}).get('value')
            if sb_url:
                break

    if not sb_url:
        return {"error": "No ScienceBase URL in Handle response"}

    # --- Extract ScienceBase item ID ---
    m = re.search(r'/catalog/item/([a-zA-Z0-9]+)', sb_url)
    if not m:
        return {"error": f"Cannot parse item ID from: {sb_url}"}
    item_id = m.group(1)

    # --- Fetch collection-level metadata ---
    api_url = f"https://www.sciencebase.gov/catalog/item/{item_id}?format=json"
    try:
        r = self._get_with_retry(api_url)
        return {"source": "USGS ScienceBase Catalog", "format": "json", "data": r.json()}
    except json.JSONDecodeError:
        return {"error": "ScienceBase returned non-JSON"}
    except Exception as e:
        return {"error": f"ScienceBase API failed: {e}"}

