    if doi_landing_page:
        m = re.search(r'/collections/[^/]+/(\d+)', doi_landing_page)
        if m:
            collection_id = m.group(1)

    # Path 2: Extract from dataset_url
    if not collection_id and dataset_url:
        m = re.search(r'/collections/[^/]+/(\d+)', dataset_url)
        if m:
            collection_id = m.group(1)

    # Path 3: Extract from DOI (Figshare collection DOI: 10.XXXXX/prefix.c.1234567)
    if not collection_id and doi:
        m = re.search(r'\.c\.(\d+)$', doi)
        if m:
            collection_id = m.group(1)
        else:
            m = re.search(r'(\d+)$', doi)
            if m:
                collection_id = m.group(1)

    # Path 4: Generic trailing digits from dataset_url
    if not collection_id and dataset_url:
        m = re.search(r'/(\d+)/?$', dataset_url)
        if m:
            collection_id = m.group(1)

    # Path 5: Generic trailing digits from doi_landing_page
    if not collection_id and doi_landing_page:
        m = re.search(r'/(\d+)/?$', doi_landing_page)
        if m:
            collection_id = m.group(1)

    if not collection_id:
        return {"error": "无法从提供的参数中解析出 Figshare collection ID，请提供有效的 doi、dataset_url 或 doi_landing_page"}

    url = f"https://api.figshare.com/v2/collections/{collection_id}"
    response = self._get_with_retry(url)

    if not response or not hasattr(response, 'text'):
