    except json.JSONDecodeError as e:
        return {"error": f"Figshare API JSON 解析失败: {e}", "raw": response.text[:1000] if response and hasattr(response, 'text') else ""}

    return {
        "source": "Figshare",
        "format": "json",
        "data": data
    }

