    # --- Fetch the catalog JSONL file ---
    catalog_url = (
        "https://raw.githubusercontent.com/samapriya/"
        "awesome-gee-community-datasets/master/community_datasets.jsonl"
    )

    response = self._get_with_retry(catalog_url)
