import json
import re

def fetch_hrsl_hdx(self, **kwargs):
    """
    Fetch collection-level metadata for HRSL (High Resolution Settlement Layer)
    from the HDX CKAN API (Humanitarian Data Exchange).

    Dynamically discovers the correct package ID via package_search,
    then retrieves full metadata via package_show.
    """
    dataset_name = kwargs.get('dataset_name', '')
    dataset_url = kwargs.get('dataset_url', '')
    doi = kwargs.get('doi', '')
    doi_landing_page = kwargs.get('doi_landing_page', '')

    # ---- Build search query from available inputs ----
    search_terms = []

    if dataset_name:
        name_lower = dataset_name.lower()
        if 'hrsl' in name_lower:
            search_terms.append('hrsl')
        if 'high resolution settlement layer' in name_lower:
            search_terms.append('"High Resolution Settlement Layer"')
        if not search_terms and 'population' in name_lower:
            search_terms.append('"population density"')

    if not search_terms and dataset_url:
        url_lower = dataset_url.lower()
        if 'high-resolution-population-density' in url_lower or 'population-density' in url_lower:
            search_terms.append('"population density"')
        if 'hrsl' in url_lower:
            search_terms.append('hrsl')

    # If no search terms could be extracted, return error
    if not search_terms:
        return {"error": "缺少关键参数：无法从 dataset_name 或 dataset_url 中提取搜索关键词以定位 HRSL 数据集"}

    query = ' OR '.join(search_terms)

    # ---- Step 1: Search for matching HRSL dataset under Meta organization ----
    search_url = (
        f"https://data.humdata.org/api/3/action/package_search"
        f"?q={query}&fq=organization:meta&rows=1"
    )

    resp = self._get_with_retry(search_url)

    try:
        search_data = resp.json()
    except json.JSONDecodeError:
        return {"error": "HDX search API returned non-JSON response", "status": "parse_error"}

    if not search_data.get('success'):
        return {"error": "HDX search API indicated failure", "raw": search_data}

    result = search_data.get('result', {})
    if result.get('count', 0) == 0:
        return {"error": "No HRSL datasets found on HDX under Meta organization"}

    results = result.get('results', [])
    if not results or len(results) == 0:
        return {"error": "Search results list is empty"}

    package_name = results[0].get('name')
    if not package_name:
        return {"error": "Could not extract package name/ID from search results"}

    # ---- Step 2: Get full package metadata via package_show ----
    show_url = f"https://data.humdata.org/api/3/action/package_show?id={package_name}"
    show_resp = self._get_with_retry(show_url)

    try:
        show_data = show_resp.json()
    except json.JSONDecodeError:
        return {"error": "HDX package_show API returned non-JSON response", "status": "parse_error"}

    if not show_data.get('success'):
        return {"error": "HDX package_show API indicated failure", "raw": show_data}

    return {
        "source": "HDX (Humanitarian Data Exchange)",
        "format": "json",
        "data": show_data
    }
